package org.archive.webservices.ars.util

import scala.reflect.runtime.universe._

import io.circe.syntax._
import json._
import com.github.andyglow.jsonschema.AsCirce._
import json.schema.Version._

object JsonSchemaUtil {

  /**
   * Extend a schema object generated by scala-jsonschema with param / property-level
   * @title
   *   annotations as defined by parameter class T.
   *
   * scala-jsonschema does not currently support property-level titles:
   * https://github.com/andyglow/scala-jsonschema/issues/290
   */
  def extendJsonSchemaWithParamTitles[T: TypeTag](schema: io.circe.Json): io.circe.Json = {
    val paramNameTitleMap =
      typeOf[T].typeSymbol.info.decls
        .find(d => d.isMethod && d.asMethod.isPrimaryConstructor)
        .get
        .typeSignature
        .paramLists
        .head
        .filter(_.annotations.nonEmpty)
        .map(param =>
          (
            param.name.toString,
            param.annotations
              .filter(_.tree.children.head.toString.endsWith("json.schema.title"))
              .headOption))
        .filter(_._2.nonEmpty)
        .map { case (paramName, title) =>
          (paramName, title.get.tree.children.tail.head.toString.replace("\"", ""))
        }
        .toMap
    schema.hcursor
      .downField("properties")
      .withFocus(_.mapObject(_.deepMerge(
        paramNameTitleMap.mapValues(title => Map("title" -> title)).asJson.asObject.get)))
      .top
      .get
  }

  /**
   * Extend schema with param-level title annotations and serialize as JSON Schema Draft 2020-12.
   */
  def finalSchemaJson[T: TypeTag](schema: json.Schema[T]): io.circe.Json = {
    extendJsonSchemaWithParamTitles[T](schema.asCirce(Draft12("")))
  }
}
